[66] // 更新用户信息（仅管理员或用户本人）
[67] export const updateUser = async (
[68]   userId: number,
[69]   input: UpdateUserInput,
[70]   requestingUserId?: number,
[71]   requestingUserRole?: Role
[72] ) => {
[73]   // 验证权限：管理员可以更新任何用户，普通用户只能更新自己的信息
[74]   if (requestingUserRole !== Role.ADMIN && requestingUserId !== userId) {
[75]     throw new ForbiddenError('You are not allowed to update this user');
[76]   }
[77] 
[78]   // 普通用户不能修改自己的角色
[79]   if (input.role && requestingUserRole !== Role.ADMIN) {
[80]     throw new ForbiddenError('Only administrators can change user roles');
[81]   }
[82] 
[83]   // 检查邮箱是否已存在（如果需要更新邮箱，但这里邮箱不允许更新）
[84]   // 邮箱作为唯一标识符，不允许通过此端点修改，如需修改邮箱应单独实现
[85] 
[86]   const updatedUser = await prisma.user.update({
[87]     where: { id: userId },
[88]     data: {
[89]       name: input.name,
[90]       bio: input.bio,
[91]       avatar: input.avatar,
[92]       role: input.role,
[93]     },
[94]     select: {
[95]       id: true,
[96]       email: true,
[97]       name: true,
[98]       bio: true,
[99]       avatar: true,
[100]       role: true,
