[109] // 修改密码（仅用户本人）
[110] export const changePassword = async (
[111]   userId: number,
[112]   input: ChangePasswordInput,
[113]   requestingUserId?: number,
[114]   requestingUserRole?: Role
[115] ) => {
[116]   // 只能修改自己的密码，除非是管理员
[117]   if (requestingUserRole !== Role.ADMIN && requestingUserId !== userId) {
[118]     throw new ForbiddenError('You are not allowed to change this user\'s password');
[119]   }
[120] 
[121]   // 获取用户并验证当前密码
[122]   const user = await prisma.user.findUnique({
[123]     where: { id: userId },
[124]   });
[125] 
[126]   if (!user) {
[127]     throw new NotFoundError('User not found');
[128]   }
[129] 
[130]   // 验证当前密码（如果是管理员修改他人密码，是否需要验证？这里我们要求管理员也提供当前密码）
[131]   const isValidPassword = await bcrypt.compare(input.currentPassword, user.passwordHash);
[132]   if (!isValidPassword) {
[133]     throw new BadRequestError('Current password is incorrect');
[134]   }
[135] 
[136]   // 哈希新密码
[137]   const hashedNewPassword = await bcrypt.hash(input.newPassword, 10);
[138] 
[139]   // 更新密码
[140]   await prisma.user.update({
[141]     where: { id: userId },
[142]     data: {
[143]       passwordHash: hashedNewPassword,
[144]     },
[145]   });
[146] 
[147]   return { message: 'Password updated successfully' };
[148] };
