[150] // 删除用户（仅管理员）
[151] export const deleteUser = async (userId: number, requestingUserRole?: Role) => {
[152]   if (requestingUserRole !== Role.ADMIN) {
[153]     throw new ForbiddenError('Only administrators can delete users');
[154]   }
[155] 
[156]   // 检查用户是否存在
[157]   const user = await prisma.user.findUnique({
[158]     where: { id: userId },
[159]   });
[160] 
[161]   if (!user) {
[162]     throw new NotFoundError('User not found');
[163]   }
[164] 
[165]   // 删除用户（级联删除由Prisma Schema中的onDelete Cascade处理）
[166]   await prisma.user.delete({
[167]     where: { id: userId },
[168]   });
[169] 
