import { Category, BlogStatus } from '@prisma/client';
import prisma, { PaginationParams, PaginatedResult, buildPaginationOptions, createPaginatedResponse } from '../db';
import { BadRequestError, NotFoundError, ConflictError } from '../utils/AppError';

export interface CreateCategoryInput {
  name: string;
  slug: string;
  description?: string;
}

export interface UpdateCategoryInput {
  name?: string;
  slug?: string;
  description?: string;
}

export interface GetCategoriesOptions extends PaginationParams {}

export interface GetCategoryBlogsOptions extends PaginationParams {
  status?: string;
}

// 创建分类
export const createCategory = async (input: CreateCategoryInput) => {
  const { name, slug, description } = input;

  // 检查slug是否唯一
  const existingCategory = await prisma.category.findUnique({
    where: { slug },
  });
  if (existingCategory) {
    throw new ConflictError('Category with this slug already exists');
  }

  // 检查name是否唯一
  const existingName = await prisma.category.findUnique({
    where: { name },
  });
  if (existingName) {
    throw new ConflictError('Category with this name already exists');
  }

  const category = await prisma.category.create({
    data: {
      name,
      slug,
      description,
    },
    select: {
      id: true,
      name: true,
      slug: true,
      description: true,
      createdAt: true,
      _count: {
        select: {
          blogs: true,
        },
      },
    },
  });

  return category;
};

// 根据ID获取分类（包含博客数量）
export const getCategoryById = async (categoryId: number) => {
  const category = await prisma.category.findUnique({
    where: { id: categoryId },
    select: {
      id: true,
      name: true,
      slug: true,
      description: true,
      createdAt: true,
      _count: {
        select: {
          blogs: true,
        },
      },
    },
  });

  if (!category) {
    throw new NotFoundError('Category not found');
  }

  return category;
};

// 获取分类列表（支持分页）
export const getCategories = async (options: GetCategoriesOptions) => {
  const { skip, take, page, pageSize } = buildPaginationOptions(options);

  const [categories, total] = await Promise.all([
    prisma.category.findMany({
      skip,
      take,
      select: {
        id: true,
        name: true,
        slug: true,
        description: true,
        createdAt: true,
        _count: {
          select: {
            blogs: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    }),
    prisma.category.count(),
  ]);

  return createPaginatedResponse(categories, total, page, pageSize);
};

// 更新分类
export const updateCategory = async (categoryId: number, input: UpdateCategoryInput) => {
  // 检查分类是否存在
  const category = await prisma.category.findUnique({
    where: { id: categoryId },
  });
  if (!category) {
    throw new NotFoundError('Category not found');
  }

  // 如果提供slug，检查唯一性（排除自身）
  if (input.slug && input.slug !== category.slug) {
    const existingSlug = await prisma.category.findUnique({
      where: { slug: input.slug },
    });
    if (existingSlug) {
      throw new ConflictError('Category with this slug already exists');
    }
  }

  // 如果提供name，检查唯一性（排除自身）
  if (input.name && input.name !== category.name) {
    const existingName = await prisma.category.findUnique({
      where: { name: input.name },
    });
    if (existingName) {
      throw new ConflictError('Category with this name already exists');
    }
  }

  const updatedCategory = await prisma.category.update({
    where: { id: categoryId },
    data: {
      name: input.name,
