import { Tag, BlogStatus } from '@prisma/client';
import prisma, { PaginationParams, PaginatedResult, buildPaginationOptions, createPaginatedResponse } from '../db';
import { BadRequestError, NotFoundError, ConflictError } from '../utils/AppError';

export interface CreateTagInput {
  name: string;
  slug: string;
}

export interface UpdateTagInput {
  name?: string;
  slug?: string;
}

export interface GetTagsOptions extends PaginationParams {
  sortBy?: string;
  order?: 'asc' | 'desc';
}

export interface GetTagBlogsOptions extends PaginationParams {
  status?: string;
}

// 创建标签
export const createTag = async (input: CreateTagInput) => {
  const { name, slug } = input;

  // 检查slug是否唯一
  const existingTag = await prisma.tag.findUnique({
    where: { slug },
  });
  if (existingTag) {
    throw new ConflictError('Tag with this slug already exists');
  }

  // 检查name是否唯一
  const existingName = await prisma.tag.findUnique({
    where: { name },
  });
  if (existingName) {
    throw new ConflictError('Tag with this name already exists');
  }

  const tag = await prisma.tag.create({
    data: {
      name,
      slug,
    },
    select: {
      id: true,
      name: true,
      slug: true,
      createdAt: true,
      _count: {
        select: {
          blogTags: true,
        },
      },
    },
  });

  return tag;
};

// 根据ID获取标签（包含博客数量）
export const getTagById = async (tagId: number) => {
  const tag = await prisma.tag.findUnique({
    where: { id: tagId },
    select: {
      id: true,
      name: true,
      slug: true,
      createdAt: true,
      _count: {
        select: {
          blogTags: true,
        },
      },
    },
  });

  if (!tag) {
    throw new NotFoundError('Tag not found');
  }

  return tag;
};

// 获取标签列表（支持分页、排序）
export const getTags = async (options: GetTagsOptions) => {
  const { skip, take, page, pageSize, sortBy = 'createdAt', order = 'desc' } = options;

  // 构建orderBy条件
  let orderBy: any = { [sortBy]: order };

  // 如果按博客数量排序，需要使用聚合查询
  if (sortBy === 'blogCount') {
    // 使用Prisma的聚合和分组查询
    const tagsWithCounts = await prisma.tag.findMany({
      skip,
      take,
      select: {
        id: true,
        name: true,
        slug: true,
        createdAt: true,
        _count: {
          select: {
            blogTags: true,
          },
        },
      },
      orderBy: {
        blogTags: {
          _count: order,
        },
      },
    });

    const total = await prisma.tag.count();

    return createPaginatedResponse(tagsWithCounts, total, page, pageSize);
  }

  const [tags, total] = await Promise.all([
    prisma.tag.findMany({
      skip,
      take,
      select: {
        id: true,
        name: true,
        slug: true,
        createdAt: true,
        _count: {
          select: {
            blogTags: true,
          },
        },
      },
      orderBy,
    }),
    prisma.tag.count(),
  ]);

  return createPaginatedResponse(tags, total, page, pageSize);
};

// 更新标签
export const updateTag = async (tagId: number, input: UpdateTagInput) => {
  // 检查标签是否存在
  const tag = await prisma.tag.findUnique({
    where: { id: tagId },
  });
  if (!tag) {
    throw new NotFoundError('Tag not found');
  }

  // 如果提供slug，检查唯一性（排除自身）
  if (input.slug && input.slug !== tag.slug) {
    const existingSlug = await prisma.tag.findUnique({
      where: { slug: input.slug },
    });
    if (existingSlug) {
      throw new ConflictError('Tag with this slug already exists');
    }
  }

  // 如果提供name，检查唯一性（排除自身）
  if (input.name && input.name !== tag.name) {
    const existingName = await prisma.tag.findUnique({
      where: { name: input.name },
    });
    if (existingName) {
      throw new ConflictError('Tag with this name already exists');
    }
  }

  const updatedTag = await prisma.tag.update({
    where: { id: tagId },
    data: {
      name: input.name,
      slug: input.slug,
    },
    select: {
      id: true,
      name: true,
      slug: true,
      createdAt: true,
      _count: {
        select: {
          blogTags: true,
        },
      },
    },
  });

  return updatedTag;
};

// 删除标签
export const deleteTag = async (tagId: number) => {
  // 检查标签是否存在
  const tag = await prisma.tag.findUnique({
    where: { id: tagId },
  });
  if (!tag) {
    throw new NotFoundError('Tag not found');
  }

  // 删除标签（外键约束已设置为Cascade，关联的BlogTag记录将被删除）
  await prisma.tag.delete({
    where: { id: tagId },
  });

  return { message: 'Tag deleted successfully' };
};

// 获取标签下的博客列表
export const getTagBlogs = async (tagId: number, options: GetTagBlogsOptions) => {
  // 检查标签是否存在
  const tag = await prisma.tag.findUnique({
    where: { id: tagId },
  });
  if (!tag) {
    throw new NotFoundError('Tag not found');
  }

  const { skip, take, page, pageSize } = buildPaginationOptions(options);
  const { status } = options;

  // 构建where条件
  const where: any = {
    blogTags: {
      some: {
        tagId,
      },
    },
  };

  // 根据状态筛选（如果提供）
  if (status) {
    if (status === 'published') {
      where.status = BlogStatus.PUBLISHED;
    } else if (status === 'draft') {
      where.status = BlogStatus.DRAFT;
    } else {
      throw new BadRequestError('Invalid status value. Use "published" or "draft"');
    }
  }

  const [blogs, total] = await Promise.all([
    prisma.blog.findMany({
      where,
      skip,
      take,
      select: {
        id: true,
        title: true,
        excerpt: true,
        coverImage: true,
        status: true,
        viewCount: true,
        publishedAt: true,
        createdAt: true,
        updatedAt: true,
        author: {
          select: {
            id: true,
            name: true,
            avatar: true,
          },
        },
        category: {
          select: {
            id: true,
            name: true,
            slug: true,
          },
        },
        blogTags: {
          select: {
            tag: {
              select: {
                id: true,
                name: true,
                slug: true,
              },
            },
          },
        },
      },
      orderBy: {
        publishedAt: 'desc',
      },
    }),
    prisma.blog.count({ where }),
  ]);

  return createPaginatedResponse(blogs, total, page, pageSize);
};

// 获取热门标签（按使用频率排序）
export const getPopularTags = async (limit?: number) => {
  const tags = await prisma.tag.findMany({
    take: limit || 10,
    select: {
      id: true,
      name: true,
      slug: true,
      createdAt: true,
      _count: {
        select: {
          blogTags: true,
        },
      },
    },
    orderBy: {
      blogTags: {
        _count: 'desc',
      },
    },
  });

  return tags;
};

