import express from 'express';
import {
  createCategory,
  getCategory,
  getCategories,
  updateCategory,
  deleteCategory,
  getCategoryBlogs,
} from '../controllers/category.controller';
import { requireAdmin, optionalAuth } from '../middleware/auth';
import { validate } from '../middleware/validate';
import { createCategoryValidation, updateCategoryValidation } from '../validations/category.validation';

const router = express.Router();

// 创建分类（需要管理员权限）
router.post('/', requireAdmin, createCategoryValidation, validate, createCategory);

// 获取分类列表（公共API，不需要认证）
router.get('/', getCategories);

// 获取单个分类详情（公共API，不需要认证）
router.get('/:id', getCategory);

// 更新分类（需要管理员权限）
router.put('/:id', requireAdmin, updateCategoryValidation, validate, updateCategory);

// 删除分类（需要管理员权限）
router.delete('/:id', requireAdmin, deleteCategory);

// 获取分类下的博客列表（公共API，不需要认证）
router.get('/:id/blogs', getCategoryBlogs);

export default router;

