import { Request, Response } from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import * as tagService from '../services/tag.service';
import { AuthenticatedRequest } from '../middleware/auth';
import { Role } from '@prisma/client';

// 创建标签（需要管理员权限）
export const createTag = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 检查用户角色是否为管理员
  if (req.user?.role !== Role.ADMIN) {
    return res.status(403).json({
      success: false,
      error: 'Only administrators can create tags',
    });
  }

  const { name, slug } = req.body;

  const tag = await tagService.createTag({
    name,
    slug,
  });

  res.status(201).json({
    success: true,
    data: tag,
  });
});

// 获取单个标签详情
export const getTag = asyncHandler(async (req: Request, res: Response) => {
  const tagId = parseInt(req.params.id);
  if (isNaN(tagId)) {
    return res.status(400).json({
      success: false,
      error: 'Invalid tag ID',
    });
  }

  const tag = await tagService.getTagById(tagId);

  res.status(200).json({
    success: true,
    data: tag,
  });
});

// 获取标签列表（支持分页、热门标签排序）
export const getTags = asyncHandler(async (req: Request, res: Response) => {
  const page = req.query.page ? parseInt(req.query.page as string) : undefined;
  const pageSize = req.query.pageSize ? parseInt(req.query.pageSize as string) : undefined;
  const sortBy = req.query.sortBy as string | undefined;
  const order = req.query.order as 'asc' | 'desc' | undefined;

  const result = await tagService.getTags({
    page,
    pageSize,
    sortBy,
    order,
  });

  res.status(200).json({
    success: true,
    data: result,
  });
});

// 更新标签（管理员权限）
export const updateTag = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 检查用户角色是否为管理员
  if (req.user?.role !== Role.ADMIN) {
    return res.status(403).json({
      success: false,
      error: 'Only administrators can update tags',
    });
  }

  const tagId = parseInt(req.params.id);
  if (isNaN(tagId)) {
    return res.status(400).json({
      success: false,
      error: 'Invalid tag ID',
    });
  }

  const { name, slug } = req.body;

  const updatedTag = await tagService.updateTag(tagId, {
    name,
    slug,
  });

  res.status(200).json({
    success: true,
    data: updatedTag,
  });
});

// 删除标签（管理员权限）
export const deleteTag = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 检查用户角色是否为管理员
  if (req.user?.role !== Role.ADMIN) {
    return res.status(403).json({
      success: false,
      error: 'Only administrators can delete tags',
    });
  }

  const tagId = parseInt(req.params.id);
  if (isNaN(tagId)) {
    return res.status(400).json({
      success: false,
      error: 'Invalid tag ID',
    });
  }

  const result = await tagService.deleteTag(tagId);

  res.status(200).json({
    success: true,
    message: result.message,
  });
});

// 获取标签下的博客列表
export const getTagBlogs = asyncHandler(async (req: Request, res: Response) => {
  const tagId = parseInt(req.params.id);
  if (isNaN(tagId)) {
    return res.status(400).json({
      success: false,
      error: 'Invalid tag ID',
    });
  }

  const page = req.query.page ? parseInt(req.query.page as string) : undefined;
  const pageSize = req.query.pageSize ? parseInt(req.query.pageSize as string) : undefined;
  const status = req.query.status as string | undefined;

  const result = await tagService.getTagBlogs(tagId, {
    page,
    pageSize,
    status,
  });

  res.status(200).json({
    success: true,
    data: result,
  });
});

// 获取热门标签（按使用频率排序）
export const getPopularTags = asyncHandler(async (req: Request, res: Response) => {
  const limit = req.query.limit ? parseInt(req.query.limit as string) : undefined;

  const tags = await tagService.getPopularTags(limit);

  res.status(200).json({
    success: true,
    data: tags,
  });
});

